import { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { signOut } from 'firebase/auth';
import { auth } from '../../firebase';
import '../../styles/dashboard.css';

const navItems = [
  { icon: '🏠', label: 'Dashboard', path: '/dashboard' },
  { icon: '📁', label: 'Projects', path: '/projects' },
  { icon: '✅', label: 'Tasks', path: '/tasks' },
  { icon: '💬', label: 'Messages', path: '/messages' },
  { icon: '📊', label: 'Analytics', path: '/analytics' },
  { icon: '📨', label: 'Invitations', path: '/invitations' },
];

const bottomItems = [
  { icon: '👥', label: 'Team', path: '/settings' },
  { icon: '⚙️', label: 'Settings', path: '/settings' },
];

export default function Sidebar({ active }) {
  const navigate = useNavigate();
  const location = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);

  const isActive = (path) => location.pathname === path;

  const handleLogout = async () => {
    try {
      await signOut(auth);
      navigate('/signin');
    } catch (error) {
      console.error('Logout error:', error);
    }
  };

  const handleNavigate = (path) => {
    navigate(path);
    setMobileOpen(false);
  };

  return (
    <>
      {/* Mobile Top Bar */}
      <div style={{
        display: 'none',
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 200,
        background: '#070d1a',
        borderBottom: '1px solid rgba(255,255,255,0.07)',
        padding: '12px 16px',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}
        className="mobile-topbar"
      >
        {/* Logo */}
        <div
          style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}
          onClick={() => handleNavigate('/dashboard')}
        >
          <div style={{
            width: '30px', height: '30px',
            background: 'linear-gradient(135deg, #3b82f6, #6366f1)',
            borderRadius: '8px',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontFamily: 'Syne, sans-serif', fontWeight: '700',
            fontSize: '14px', color: 'white',
          }}>D</div>
          <span style={{
            fontFamily: 'Syne, sans-serif',
            fontSize: '15px', fontWeight: '600', color: '#f8fafc',
          }}>DevCollab</span>
        </div>

        {/* Hamburger Button */}
        <button
          onClick={() => setMobileOpen(!mobileOpen)}
          style={{
            background: 'rgba(255,255,255,0.06)',
            border: '1px solid rgba(255,255,255,0.1)',
            borderRadius: '8px',
            padding: '6px 10px',
            cursor: 'pointer',
            display: 'flex',
            flexDirection: 'column',
            gap: '4px',
          }}
        >
          <span style={{
            display: 'block', width: '18px', height: '2px',
            background: mobileOpen ? '#60a5fa' : '#94a3b8',
            borderRadius: '2px',
            transition: 'all 0.2s',
            transform: mobileOpen ? 'rotate(45deg) translate(4px, 4px)' : 'none',
          }} />
          <span style={{
            display: 'block', width: '18px', height: '2px',
            background: mobileOpen ? '#60a5fa' : '#94a3b8',
            borderRadius: '2px',
            transition: 'all 0.2s',
            opacity: mobileOpen ? 0 : 1,
          }} />
          <span style={{
            display: 'block', width: '18px', height: '2px',
            background: mobileOpen ? '#60a5fa' : '#94a3b8',
            borderRadius: '2px',
            transition: 'all 0.2s',
            transform: mobileOpen ? 'rotate(-45deg) translate(4px, -4px)' : 'none',
          }} />
        </button>
      </div>

      {/* Mobile Overlay */}
      {mobileOpen && (
        <div
          onClick={() => setMobileOpen(false)}
          style={{
            display: 'none',
            position: 'fixed',
            inset: 0,
            background: 'rgba(0,0,0,0.5)',
            zIndex: 150,
          }}
          className="mobile-overlay"
        />
      )}

      {/* Sidebar */}
      <aside
        className="sidebar"
        style={{
          transform: mobileOpen ? 'translateX(0)' : undefined,
        }}
      >
        {/* Logo */}
        <div
          className="sidebar-logo"
          onClick={() => handleNavigate('/dashboard')}
          style={{ cursor: 'pointer' }}
        >
          <div className="sidebar-logo-icon">D</div>
          <span className="sidebar-logo-text">DevCollab</span>
        </div>

        {/* Main Nav */}
        <div className="sidebar-section-label">Main Menu</div>
        <nav className="sidebar-nav">
          {navItems.map((item) => (
            <button
              key={item.label}
              className={`sidebar-item ${isActive(item.path) ? 'active' : ''}`}
              onClick={() => handleNavigate(item.path)}
            >
              <span className="item-icon">{item.icon}</span>
              {item.label}
            </button>
          ))}
        </nav>

        {/* Bottom Nav */}
        <div className="sidebar-section-label">Settings</div>
        <nav className="sidebar-nav">
          {bottomItems.map((item) => (
            <button
              key={item.label}
              className={`sidebar-item ${isActive(item.path) ? 'active' : ''}`}
              onClick={() => handleNavigate(item.path)}
            >
              <span className="item-icon">{item.icon}</span>
              {item.label}
            </button>
          ))}
        </nav>

        {/* User Card + Logout */}
        <div className="sidebar-bottom">
          <div className="user-card">
            <div className="user-avatar">
              {auth.currentUser?.displayName?.[0] || 'U'}
            </div>
            <div className="user-info">
              <div className="user-name">
                {auth.currentUser?.displayName || 'User'}
              </div>
              <div className="user-role">{auth.currentUser?.email}</div>
            </div>
          </div>

          <button
            onClick={handleLogout}
            style={{
              width: '100%',
              marginTop: '8px',
              padding: '9px 12px',
              borderRadius: '10px',
              border: '1px solid rgba(239, 68, 68, 0.25)',
              background: 'rgba(239, 68, 68, 0.08)',
              color: '#f87171',
              fontSize: '13px',
              fontWeight: '500',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '8px',
              fontFamily: 'DM Sans, sans-serif',
              transition: 'all 0.2s',
            }}
          >
            🚪 Logout
          </button>
        </div>
      </aside>
    </>
  );
}